interface Trace { recordId: string; stage: string; ts: number; status: string; }
class FineGrainedTracker {
  constructor(private store: KVStore) {}
  async track(t: Trace) { await this.store.put(`trace:${t.recordId}:${t.ts}`, t); }
  async history(id: string): Promise<Trace[]> {
    return (await this.store.scan(`trace:${id}:`)).sort((a,b)=>a.ts-b.ts);
  }
}
